from pathlib import Path

ROSTER=Path('roster/index.html')
if not ROSTER.exists():
    raise RuntimeError('roster/index.html is required for Roster power tools')
page=ROSTER.read_text(encoding='utf-8')
if 'id="roster-power-tools-script"' in page:
    print('Roster power tools already injected')
    raise SystemExit(0)
if 'id="roster-product-cards-script"' not in page or 'id="rosterFilters"' not in page:
    raise RuntimeError('Roster product cards must be enhanced before power tools')

CSS='''<style id="roster-power-tools-style">.roster-power{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:-3px 0 14px;padding:11px 12px;border:1px solid #263a54;border-radius:15px;background:#09121f}.roster-power-copy{min-width:240px;flex:1}.roster-power-copy b{display:block;font-size:10px;color:#d6e4f6}.roster-power-copy span{display:block;margin-top:3px;color:#7588a5;font-size:9px;line-height:1.45}.roster-power-actions{display:flex;gap:7px;flex-wrap:wrap}.roster-power-actions button{min-height:36px;padding:8px 11px;border:1px solid #2d425e;border-radius:10px;background:#0c1726;color:#cbd9ec;font:850 10px/1 system-ui;cursor:pointer}.roster-power-actions button:hover,.roster-power-actions button:focus-visible{outline:none;border-color:#55e5ff;background:#102136}.roster-power-status{width:100%;margin:0;color:#8294af;font-size:9px;line-height:1.4}.roster-power-status.ok{color:#77e7c0}.roster-power-status.warn{color:#ffd27c}@media(max-width:620px){.roster-power{align-items:stretch}.roster-power-actions{width:100%}.roster-power-actions button{flex:1}.roster-power-copy{min-width:0}}</style>'''
BLOCK='''<section id="rosterPowerTools" class="roster-power" aria-label="Compartir y exportar vista del roster"><div class="roster-power-copy"><b>VISTA COMPARTIBLE</b><span>Búsqueda, orden y filtro se guardan en la URL. “Siguiendo” siempre usa la Watchlist local de quien abre el enlace.</span></div><div class="roster-power-actions"><button id="rosterCopyView" type="button">Copiar vista</button><button id="rosterExportCsv" type="button">Exportar CSV</button><button id="rosterResetView" type="button">Restablecer</button></div><p id="rosterPowerStatus" class="roster-power-status" aria-live="polite">El CSV exporta exactamente la vista actual y no envía datos a ningún servidor.</p></section>'''
marker='<div id="rosterSortNote"'
idx=page.find(marker)
if idx==-1: raise RuntimeError('Roster sort note marker missing for power tools')
page=page[:idx]+BLOCK+page[idx:]
JS='''<script id="roster-power-tools-script">(()=>{const search=document.getElementById('q'),order=document.getElementById('sort'),filterBox=document.getElementById('rosterFilters'),copyBtn=document.getElementById('rosterCopyView'),csvBtn=document.getElementById('rosterExportCsv'),resetBtn=document.getElementById('rosterResetView'),status=document.getElementById('rosterPowerStatus');if(!search||!order||!filterBox||!copyBtn||!csvBtn||!resetBtn||!status||typeof HEROES==='undefined')return;const VALID_SORT=new Set(['score','wr','ban','pick','name']),VALID_FILTER=new Set(['all','watch','editorial','top20']);function activeFilter(){return filterBox.querySelector('[data-roster-filter][aria-pressed="true"]')?.dataset.rosterFilter||'all'}function watchSet(){try{const v=JSON.parse(localStorage.getItem('mf_watchlist_v1')||'[]');return new Set(Array.isArray(v)?v:[])}catch{return new Set()}}function setStatus(msg,kind=''){status.textContent=msg;status.className='roster-power-status'+(kind?' '+kind:'')}function syncUrl(){const u=new URL(location.href),needle=search.value.trim(),sortValue=VALID_SORT.has(order.value)?order.value:'score',filterValue=activeFilter();if(needle)u.searchParams.set('q',needle);else u.searchParams.delete('q');if(sortValue!=='score')u.searchParams.set('sort',sortValue);else u.searchParams.delete('sort');if(filterValue!=='all')u.searchParams.set('filter',filterValue);else u.searchParams.delete('filter');history.replaceState(null,'',u.pathname+(u.searchParams.toString()?'?'+u.searchParams.toString():'')+u.hash)}function visibleRows(){const watched=watchSet(),needle=search.value.trim().toLowerCase(),f=activeFilter(),key=VALID_SORT.has(order.value)?order.value:'score';let rows=HEROES.filter(h=>h.name.toLowerCase().includes(needle)&&(f==='all'||f==='watch'&&watched.has(h.name)||f==='editorial'&&h.editorial||f==='top20'&&Number(h.rank)<=20));rows.sort((a,b)=>key==='name'?a.name.localeCompare(b.name):(Number(b[key]??-1)-Number(a[key]??-1))||a.name.localeCompare(b.name));return rows}function safeCell(value){let s=value==null?'':String(value);if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}function csvText(){const header=['MetaRank','Hero','MetaScore','WR_pp','Ban_pp','Pick_pp','Coverage'];const rows=visibleRows().map(h=>[h.rank,h.name,h.score,h.wr,h.ban,h.pick,h.editorial?'EDITORIAL + LIVE':'LIVE']);return '\ufeff'+[header,...rows].map(r=>r.map(safeCell).join(',')).join('\r\n')}async function copyView(){syncUrl();const value=location.href;try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(value);else{const t=document.createElement('textarea');t.value=value;t.setAttribute('readonly','');t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();document.execCommand('copy');t.remove()}setStatus('Vista copiada. El filtro “Siguiendo” se resolverá con la Watchlist local de quien abra el enlace.','ok')}catch{setStatus('No pudimos copiar automáticamente. Puedes copiar la URL desde la barra del navegador.','warn')}}function exportCsv(){const rows=visibleRows(),blob=new Blob([csvText()],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='meta-forge-roster.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),0);setStatus(`CSV exportado: ${rows.length} ${rows.length===1?'héroe':'héroes'} de la vista actual.`,'ok')}function applyInitial(){const params=new URLSearchParams(location.search),sq=params.get('q')||'',ss=params.get('sort')||'score',sf=params.get('filter')||'all';search.value=sq;order.value=VALID_SORT.has(ss)?ss:'score';const target=filterBox.querySelector(`[data-roster-filter="${VALID_FILTER.has(sf)?sf:'all'}"]`)||filterBox.querySelector('[data-roster-filter="all"]');target?.click();syncUrl()}search.addEventListener('input',syncUrl);order.addEventListener('change',syncUrl);filterBox.addEventListener('click',e=>{if(e.target.closest('[data-roster-filter]'))queueMicrotask(syncUrl)});copyBtn.addEventListener('click',copyView);csvBtn.addEventListener('click',exportCsv);resetBtn.addEventListener('click',()=>{search.value='';order.value='score';filterBox.querySelector('[data-roster-filter="all"]')?.click();const u=new URL(location.href);['q','sort','filter'].forEach(k=>u.searchParams.delete(k));history.replaceState(null,'',u.pathname+(u.searchParams.toString()?'?'+u.searchParams.toString():'')+u.hash);setStatus('Vista restablecida.','ok')});applyInitial()})();</script>'''
page=page.replace('</head>',CSS+'</head>',1)
page=page.replace('</body>',JS+'</body>',1)
ROSTER.write_text(page,encoding='utf-8')
print('Roster power tools injected: shareable q/sort/filter state + current-view CSV export')
